public static String convertDatesToWeekdays(String date) {
  String weekdays = "SatSunMonTueWedThuFri";
  String[] monthDays = { "31", "28", "31", "30", "31", "30", "31", "31", "30", "31", "30", "31" };

  String[] dateSplit = date.split(" ");
  String monthStr = dateSplit[0];
  String dayStr = dateSplit[1];
  String yearStr = dateSplit[2];

  int month = Integer.parseInt(monthStr);
  int day = Integer.parseInt(dayStr);
  int year = Integer.parseInt(yearStr);

  int firstDay = (3 * (1 + month - 1) / 5 + year + year / 4 - year / 100 + year / 400) % 7 + 1;
  int tempDay = firstDay + monthDays[month - 1] + day;
  int weekday = tempDay % 7 + 1;

  return "'" + weekdays.substring(weekday - 1, weekday) + "' " + day + " " + date + ".";
}

public int[] twoSum(int[] nums, int target) {
