int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[left] <= nums[mid]) {
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public static double trimMean(int[] arr) {
    int numOfElements = arr.length;
    int sampleSize = 0.95 * numOfElements;
    int[] sortedArr = arr.clone();
    Arrays.sort(sortedArr);
    int smallestIndex = (numOfElements * 0.05) - 1;
    int largestIndex = numOfElements - (numOfElements * 0.05);
    int newSize = sampleSize - (smallestIndex + largestIndex);
    int[] subset = new int[newSize];

    for (int i = smallestIndex + largestIndex; i < smallestIndex + largestIndex + newSize; i++) {
      subset[i] = sortedArr[i];
    }

    double sum = 0.0;
    for (int i = 0; i < subset.length; i++) {
      sum += subset[i];
    }

    return (sum / subset.length);
  }

