public static List<String> centerSymmetricNumbers(int n) {

    List<String> symmetricNumbers = new ArrayList<>();

    for (int i = 1; i < 10; i++) {
        String numStr = String.valueOf(i);
        if (numStr.contains("0")) {
            continue;
        }
        int length = numStr.length();
        if (length != n) {
            continue;
        }
        int leftHalfLength = n / 2;
        int rightHalfLength = n - leftHalfLength;
        String leftHalf = numStr.substring(0, leftHalfLength);
        String rightHalf = numStr.substring(leftHalfLength);
        if (!leftHalf.equals(new StringBuilder(rightHalf).reverse().toString())) {
            continue;
        }
        symmetricNumbers.add(numStr);
    }

    return symmetricNumbers;
}

public static boolean isBoomerang(int[][] points) {
