        return false;
    }

    double area = 0;
    for (int i = 0; i < points.length; i++) {
        int j = (i + 1) % points.length;
        area += points[i][1] * points[j][0] - points[i][0] * points[j][1];
    }

    return Math.abs(area) > 0.000001;
}

